function setProviderSetupMode(mode,focus=true){const formState=byId('provider-form');const simple=mode==='simple';if(focus&&state.providerSetupMode!==(simple?'simple':'auto')){if(simple){try{const detected=inferProviderQuickSetup(formState.elements.quickSetup.value);formState.elements.simpleBaseUrl.value=detected.baseUrl;if(detected.secretValue)formState.elements.simpleApiKey.value=detected.secretValue}catch{}if(formState.elements.apiKey.value)formState.elements.simpleApiKey.value=formState.elements.apiKey.value}else{formState.elements.quickSetup.value=formState.elements.simpleBaseUrl.value||formState.elements.quickSetup.value;if(formState.elements.simpleApiKey.value)formState.elements.apiKey.value=formState.elements.simpleApiKey.value}}state.providerSetupMode=simple?'simple':'auto';byId('provider-auto-setup').hidden=simple;byId('provider-simple-setup').hidden=!simple;for(const tab of byId('provider-setup-tabs').querySelectorAll('[data-provider-setup]')){tab.classList.toggle('active',tab.dataset.providerSetup===state.providerSetupMode);tab.setAttribute('aria-pressed',String(tab.dataset.providerSetup===state.providerSetupMode))}const form=byId('provider-form');form.elements.quickSetup.required=!simple;form.elements.simpleBaseUrl.required=simple;if(focus)(simple?form.elements.simpleBaseUrl:form.elements.quickSetup).focus()}
