function parseRecordLines(value){const output={};for(const rawLine of value.split('\\n')){const line=rawLine.trim();if(!line)continue;const separator=line.indexOf(':');if(separator<1)throw new Error('Ожидается ИМЯ: ЗНАЧЕНИЕ, получено «'+line+'»');const key=line.slice(0,separator).trim();const item=line.slice(separator+1).trim();if(!key||!item)throw new Error('Ожидается ИМЯ: ЗНАЧЕНИЕ, получено «'+line+'»');output[key]=item}return output}
