const profile={id:providerId,displayName:String(data.get('displayName')).trim()||providerId,enabled:data.get('enabled')==='on',baseUrl:String(data.get('baseUrl')).trim(),apiType:String(data.get('apiType')),adapterId:String(data.get('adapterId')),auth,staticHeaders:parseRecordLines(String(data.get('staticHeaders'))),secretHeaders:parseRecordLines(String(data.get('secretHeaders'))),queryParameters:parseRecordLines(String(data.get('queryParameters'))),modelsEndpoint:String(data.get('modelsEndpoint')).trim(),manualModelIds:String(data.get('manualModelIds')).split('\\n').map(item=>item.trim()).filter(Boolean),disabledModelIds:providerById(providerId)?.disabledModelIds||[],modelPricing:state.editingProvider?.modelPricing||{},preferredClient:String(data.get('preferredClient')),timeoutMs:Number(data.get('timeoutMs')),healthCheck:state.editingProvider?.healthCheck||{enabled:true,metadataTtlMs:60000,minimalInference:'on-demand'}};
const token=form.elements.portalToken.value.trim();const siteInput=byId('provider-portal-inline').hidden?'':form.elements.portalSiteUrl.value.trim();const previous=portalById(providerId)?.connection;let connection=null;if(siteInput||token){const site=new URL(siteInput||profile.baseUrl);const local=['localhost','127.0.0.1','[::1]'].includes(site.hostname);if((site.protocol!=='https:'&&!(site.protocol==='http:'&&local))||site.username||site.password||site.search||site.hash)throw Error('Укажите HTTPS-адрес сайта без ключей и параметров.');const userId=form.elements.portalUserId.value.trim();if(userId&&(!Number.isSafeInteger(Number(userId))||Number(userId)<1))throw Error('ID аккаунта должен быть положительным целым числом.');if(previous&&previous.siteUrl!==site.origin&&previous.auth.kind!=='none'&&!token)throw Error('Для другого сайта введите его токен кабинета. Старый токен на новый адрес не отправляется.');if(form.dataset.portalSecretRef&&form.dataset.portalSecretOrigin!==site.origin&&!token)throw Error('Сохранённый токен относится к другому сайту. Введите токен нового кабинета.');form.elements.portalSiteUrl.value=site.origin;connection={siteUrl:site.origin,adapterId:form.elements.portalAdapterId.value,auth:previous?.auth||{kind:'none'},autoRefresh:previous?.autoRefresh??true,refreshIntervalMs:previous?.refreshIntervalMs||300000,...(userId?{userId:Number(userId)}:{})};}
if(key&&secretRef)await api('api/secrets/'+encodeURIComponent(secretRef),{method:'PUT',body:JSON.stringify({value:key})});form.elements.apiKey.value='';form.elements.simpleApiKey.value='';await api('api/providers',{method:'POST',body:JSON.stringify(profile)});saved=true;state.editingProvider=profile;form.elements.id.disabled=true;
