/* ---------- диалог: цепочка ---------- */
function openChainDialog(chain=null){state.editingLogicalModel=chain;const form=byId('logical-model-form');form.reset();byId('logical-model-dialog-title').textContent=chain?'Изменить цепочку':'Создать цепочку';form.elements.id.disabled=Boolean(chain);if(chain){form.elements.id.value=chain.id;state.chainDraft=chain.routes.slice().sort((a,b)=>b.priority-a.priority).map(route=>({providerId:route.providerId,modelId:route.modelId,enabled:route.enabled}))}else{state.chainDraft=[];form.elements.id.value=suggestChainId()}fillChainSelects();renderChainEditor();byId('logical-model-dialog').showModal();form.elements.id.focus()}
function suggestChainId(){const existing=new Set((state.snapshot?.logicalModels||[]).map(item=>item.id));let base='chain';let index=2;let id=base;while(existing.has(id)){id=base+'-'+index;index+=1}return id}
function fillChainSelects(){const providers=(state.snapshot?.providers||[]).filter(item=>item.enabled);replaceOptions(byId('chain-provider'),providers.map(item=>[item.id,item.displayName]));fillChainModels()}
function fillChainModels(){const providerId=byId('chain-provider').value;replaceOptions(byId('chain-model'),modelsForProviderSelect(providerId).map(id=>[id,id]))}
function addChainRoute(){const providerId=byId('chain-provider').value;const modelId=byId('chain-model').value;if(!providerId||!modelId){dialogStatus('logical-model-dialog','err','Выберите провайдера и модель.');return}if(state.chainDraft.some(route=>route.providerId===providerId&&route.modelId===modelId)){dialogStatus('logical-model-dialog','err','Этот маршрут уже в цепочке.');return}state.chainDraft.push({providerId,modelId,enabled:true});renderChainEditor()}
function renderChainEditor(){const root=byId('chain-routes');root.replaceChildren();if(!state.chainDraft.length){root.append(node('p','chain-empty','Добавьте хотя бы один маршрут: выберите провайдера и модель сверху.'));return}state.chainDraft.forEach((route,index)=>{const row=node('div','chain-editor-row'+(route.enabled?'':' off'));row.draggable=true;row.dataset.index=String(index);const handle=node('span','handle','⠿');handle.title='Перетащите, чтобы изменить порядок';const pos=node('span','pos',String(index+1));const name=node('span','route-name');name.append(document.createTextNode(route.providerId+' / '+route.modelId),node('small','','приоритет '+(state.chainDraft.length-index)*10));const toggle=node('button','ctrl');toggle.type='button';toggle.textContent=route.enabled?'вкл':'выкл';toggle.title='Включить или отключить маршрут';toggle.addEventListener('click',()=>{route.enabled=!route.enabled;renderChainEditor()});const up=node('button','ctrl','↑');up.type='button';up.disabled=index===0;up.addEventListener('click',()=>moveChainRoute(index,-1));const down=node('button','ctrl','↓');down.type='button';down.disabled=index===state.chainDraft.length-1;down.addEventListener('click',()=>moveChainRoute(index,1));const remove=node('button','ctrl','×');remove.type='button';remove.addEventListener('click',()=>{state.chainDraft.splice(index,1);renderChainEditor()});row.append(handle,pos,name,toggle,up,down,remove);
row.addEventListener('dragstart',()=>{row.classList.add('dragging');state.dragIndex=index});row.addEventListener('dragend',()=>{row.classList.remove('dragging')});row.addEventListener('dragover',event=>event.preventDefault());row.addEventListener('drop',event=>{event.preventDefault();const from=state.dragIndex;if(from===undefined||from===index)return;const [moved]=state.chainDraft.splice(from,1);state.chainDraft.splice(index,0,moved);state.dragIndex=undefined;renderChainEditor()});root.append(row)})}
function moveChainRoute(index,direction){const target=index+direction;if(target<0||target>=state.chainDraft.length)return;const [moved]=state.chainDraft.splice(index,1);state.chainDraft.splice(target,0,moved);renderChainEditor()}
async function saveChain(event){event.preventDefault();const form=byId('logical-model-form');if(!state.chainDraft.length){dialogStatus('logical-model-dialog','err','Добавьте хотя бы один маршрут.');return}const routes=state.chainDraft.map((route,index)=>({providerId:route.providerId,modelId:route.modelId,priority:(state.chainDraft.length-index)*10,enabled:route.enabled}));try{const payload={id:state.editingLogicalModel?.id||form.elements.id.value.trim(),routes};await api('api/logical-models',{method:'POST',body:JSON.stringify(payload)});closeDialog('logical-model-dialog');await refresh()}catch(error){dialogStatus('logical-model-dialog','err',error.message)}}

/* ---------- диалог: профиль инструкций ---------- */
const translit={'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'e','ж':'zh','з':'z','и':'i','й':'y','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'h','ц':'c','ч':'ch','ш':'sh','щ':'sch','ъ':'','ы':'y','ь':'','э':'e','ю':'yu','я':'ya'};
function slugify(value){return String(value||'').toLowerCase().split('').map(char=>translit[char]??char).join('').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,40)||'profile'}
function openPromptProfileDialog(profile=null){state.editingPromptProfile=profile;const form=byId('prompt-profile-form');form.reset();fillPromptRouteOptions(form);byId('prompt-profile-dialog-title').textContent=profile?'Изменить профиль':'Создать профиль';form.elements.id.disabled=Boolean(profile);if(profile){form.elements.id.value=profile.id;form.elements.name.value=profile.name;form.elements.description.value=profile.description||'';form.elements.instructions.value=profile.instructions;form.elements.preferredClient.value=profile.preferredClient;form.elements.reasoningLevel.value=profile.reasoningLevel||'';setPromptRouteKind(profile.fallbackPolicy==='logical-model'?'logical-model':'provider');if(profile.preferredProviderId)form.elements.preferredProviderId.value=profile.preferredProviderId;form.elements.preferredModelId.value=profile.preferredModelId||'';if(profile.preferredLogicalModelId)form.elements.preferredLogicalModelId.value=profile.preferredLogicalModelId;form.elements.codexFlags.value=(profile.clientFlags?.codex||[]).join('\\n');form.elements.claudeFlags.value=(profile.clientFlags?.claudeCode||[]).join('\\n')}else{setPromptRouteKind('provider');form.elements.id.value=suggestProfileId('profile')}byId('prompt-profile-dialog').showModal();form.elements.name.focus()}
function suggestProfileId(base){const existing=new Set((state.snapshot?.promptProfiles||[]).map(item=>item.id));let id=base;let index=2;while(existing.has(id)){id=base+'-'+index;index+=1}return id}
function fillPromptRouteOptions(form){replaceOptions(form.elements.preferredProviderId,(state.snapshot?.providers||[]).map(profile=>[profile.id,profile.displayName]));replaceOptions(form.elements.preferredLogicalModelId,(state.snapshot?.logicalModels||[]).map(model=>[model.id,model.id]))}
function setPromptRouteKind(kind){state.promptRouteKind=kind;for(const tab of byId('prompt-route-tabs').querySelectorAll('.route-tab'))tab.classList.toggle('active',tab.dataset.proute===kind);byId('prompt-provider-route').hidden=kind!=='provider';byId('prompt-logical-route').hidden=kind!=='logical-model'}
async function savePromptProfile(event){event.preventDefault();const form=event.currentTarget;try{const logical=state.promptRouteKind==='logical-model';const reasoning=form.elements.reasoningLevel.value.trim();const id=(state.editingPromptProfile?.id||form.elements.id.value.trim()||slugify(form.elements.name.value));const providerId=form.elements.preferredProviderId.value.trim();const modelId=form.elements.preferredModelId.value.trim();const logicalModelId=form.elements.preferredLogicalModelId.value.trim();const promptProfile={id,name:form.elements.name.value.trim(),description:form.elements.description.value.trim(),instructions:form.elements.instructions.value.trim(),preferredClient:form.elements.preferredClient.value,fallbackPolicy:logical?'logical-model':'disabled',clientFlags:{codex:parseFlagLines(form.elements.codexFlags.value),claudeCode:parseFlagLines(form.elements.claudeFlags.value)},...(reasoning?{reasoningLevel:reasoning}:{}),...(logical?(logicalModelId?{preferredLogicalModelId:logicalModelId}:{}):(providerId?{preferredProviderId:providerId,...(modelId?{preferredModelId:modelId}:{})}:{}))};await api('api/prompt-profiles',{method:'POST',body:JSON.stringify(promptProfile)});closeDialog('prompt-profile-dialog');await refresh()}catch(error){dialogStatus('prompt-profile-dialog','err',error.message)}}
function parseFlagLines(value){return value.split('\\n').map(flag=>flag.trim()).filter(Boolean)}

/* ---------- диалог: привязка проекта ---------- */
function openProjectProfileDialog(profile=null){state.editingProjectProfile=profile;const form=byId('project-profile-form');form.reset();replaceOptions(form.elements.promptProfileId,(state.snapshot?.promptProfiles||[]).map(item=>[item.id,item.name+' ('+item.id+')']));byId('project-profile-dialog-title').textContent=profile?'Изменить привязку':'Привязать проект';form.elements.projectDirectory.disabled=Boolean(profile);if(profile){form.elements.projectDirectory.value=profile.projectDirectory;form.elements.promptProfileId.value=profile.promptProfileId}byId('project-profile-dialog').showModal()}
async function saveProjectProfile(event){event.preventDefault();const form=event.currentTarget;try{const projectProfile={projectDirectory:state.editingProjectProfile?.projectDirectory||form.elements.projectDirectory.value.trim(),promptProfileId:form.elements.promptProfileId.value};await api('api/project-profiles',{method:'POST',body:JSON.stringify(projectProfile)});closeDialog('project-profile-dialog');await refresh()}catch(error){dialogStatus('project-profile-dialog','err',error.message)}}

/* ---------- диалог: ключ ---------- */
function openSecretDialog(reference=''){const form=byId('secret-form');form.reset();form.elements.reference.disabled=Boolean(reference);form.elements.reference.value=reference;byId('secret-dialog').showModal();form.elements.value.focus()}
async function saveSecret(event){event.preventDefault();const form=event.currentTarget;const reference=form.elements.reference.value.trim();try{await api('api/secrets/'+encodeURIComponent(reference),{method:'PUT',body:JSON.stringify({value:form.elements.value.value})});form.elements.value.value='';closeDialog('secret-dialog');await refresh()}catch(error){form.elements.value.value='';dialogStatus('secret-dialog','err',error.message)}}

function closeDialog(id){byId(id).close();if(id==='logical-model-dialog')state.editingLogicalModel=null;if(id==='prompt-profile-dialog')state.editingPromptProfile=null;if(id==='project-profile-dialog')state.editingProjectProfile=null}

