function portalImportAdapter(siteUrl,fallback='new-api'){try{const host=new URL(siteUrl).hostname.toLowerCase();if(host==='nofx.one'||host.endsWith('.nofx.one'))return'nofx';if(['helyxai.space','www.helyxai.space'].includes(host))return'helyx'}catch{}return fallback}
function portalImportAuth(siteUrl,record){if(record?.connection.auth.kind&&record.connection.auth.kind!=='none')return record.connection.auth.kind;try{if(new URL(siteUrl).hostname.toLowerCase()==='beizhi.sylu.cc')return'bearer'}catch{}return'cookie'}
function updatePortalImportFields(){const form=byId('cookie-import-form');const bearer=form.elements.authKind.value==='bearer';byId('portal-import-raw-label').textContent=bearer?'Access Token':'Экспорт Cookie-Editor';form.elements.raw.placeholder=bearer?'Вставьте Access Token. Префикс Bearer можно оставить.':'В Cookie-Editor выберите Export → JSON и вставьте результат сюда';byId('portal-import-raw-hint').textContent=bearer?'Токен сохраняется в защищённом хранилище и не возвращается в интерфейс.':'Поддерживаются JSON, Header String и Netscape. Экспортируйте cookies текущего сайта, не всего браузера.'}
function openCookieImport(providerId,returnToOverview=false){
  const profile=providerById(providerId);if(!profile)return;
  const record=portalById(providerId);const form=byId('cookie-import-form');const dialog=byId('cookie-import-dialog');form.reset();dialog.dataset.returnToOverview=returnToOverview?'true':'false';
  const portalForm=byId('portal-form');const useLive=byId('provider-dialog').open&&portalForm.elements.providerId.value===providerId;
  form.elements.providerId.value=providerId;byId('cookie-import-provider').textContent=profile.displayName;
  form.elements.siteUrl.value=(useLive?portalForm.elements.siteUrl.value.trim():'')||record?.connection.siteUrl||new URL(profile.baseUrl).origin;
  form.elements.adapterId.replaceChildren(...(state.snapshot?.portalAdapters||[]).map(item=>option(item.id,item.displayName)));
  const selectedAdapter=(useLive?portalForm.elements.adapterId.value:'')||record?.connection.adapterId||'new-api';
  form.elements.adapterId.value=portalImportAdapter(form.elements.siteUrl.value,selectedAdapter);
  form.elements.authKind.value=portalImportAuth(form.elements.siteUrl.value,record);
  form.elements.userId.value=(useLive?portalForm.elements.userId.value:'')||record?.connection.userId||'';
  form.elements.autoRefresh.checked=useLive?portalForm.elements.autoRefresh.checked:(record?.connection.autoRefresh??true);
  byId('cookie-import-status').className='status-line';byId('cookie-import-status').textContent='';updatePortalImportFields();
  dialog.showModal();form.elements.raw.focus();
}
byId('cookie-import-form')?.elements.authKind.addEventListener('change',updatePortalImportFields);
byId('cookie-import-form')?.elements.siteUrl.addEventListener('change',event=>{const form=event.currentTarget.form;form.elements.adapterId.value=portalImportAdapter(event.currentTarget.value,form.elements.adapterId.value);form.elements.authKind.value=portalImportAuth(event.currentTarget.value);updatePortalImportFields()});
byId('cookie-import-dialog')?.addEventListener('close',()=>{const dialog=byId('cookie-import-dialog');if(dialog.dataset.returnToOverview==='true'){dialog.dataset.returnToOverview='false';renderCookieOverview();if(!byId('cookie-overview-dialog').open)byId('cookie-overview-dialog').showModal()}});

byId('cookie-import-form')?.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.currentTarget;const raw=form.elements.raw.value.trim();if(!raw)return;
  const userId=form.elements.userId.value.trim();const authKind=form.elements.authKind.value;
  const payload={providerId:form.elements.providerId.value,authKind,raw,siteUrl:form.elements.siteUrl.value.trim(),adapterId:form.elements.adapterId.value,autoRefresh:form.elements.autoRefresh.checked,refreshIntervalMs:300000,...(userId?{userId:Number(userId)}:{})};
  setStatus('cookie-import-status','busy',authKind==='bearer'?'Сохраняю Access Token и проверяю кабинет…':'Сохраняю cookies и проверяю кабинет…');
  try{
    await api('api/portals/import',{method:'POST',body:JSON.stringify(payload)});form.elements.raw.value='';await refresh();byId('cookie-import-dialog').close();
  }catch(error){setStatus('cookie-import-status','err',error.message)}
});
